BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (224::BIGINT, 'Es una profe súper buena, se le entiende muy bien la materia y lo motiva a uno a poner atención, deja muchas tareas pero no son muy largas. Súper recomendada para cualquier clase de Física que quieran llevar, quiere mucho a los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f1851627992a2f5e67d984f7e6fa665fbd847f0ff4bf8920765e64182bfb1ecf'::TEXT, ARRAY[4152]::BIGINT[]),
    (224::BIGINT, 'La profe es excelente, con esto de la pandemia de verdad sacaba un espacio por semana para poder ver en que nos podía ayudar evacuando dudas siempre en horas de consultas. Ya que en la escuela de física se decidió no hacer clases sincrónicas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '0b3b7c63281cc196e8add630bca03e57cc576c3ddf3d2ca81f1ad5cd8ec51aa6'::TEXT, ARRAY[922]::BIGINT[]),
    (224::BIGINT, 'Se nota que le apasiona el tema y lo explica bien claro. Está dispuesta a ayudar aunque sea para cosas de otros cursos. Da ejemplos dinámicos en el aula y a la vez da ejemplos similares a los exámenes. Y además, es una excelente persona, agradable e inspiradora.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2019-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'f6982626f6d5ba4ee9cea5e71e0a7f1bc792259b5c4689d3fd588368d9ba1b41'::TEXT, ARRAY[4763, 4148, 4152]::BIGINT[]),
    (224::BIGINT, 'Excelente Profesora, me dió F I Y F III, sumamente recomendada, no califica duro, las tareas son muy fáciles, lo prepara bien para el examen y para la vida, ninguna de las clases son aburridas y se vuelven muy participativas, nada más es cuestión de compromiso con el curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '2c1f2ff630b455abb9c80d73a96d667af032720e4deddd8e0ab4d1d16be3fcec'::TEXT, ARRAY[922]::BIGINT[]),
    (224::BIGINT, 'Como persona es genial, la profe es muy accesible solo que se enfoca DEMASIADO en la parte teorica y no hace tantos ejercicios como uno quisiera, pero no es una mala opción para el curso. Ella atiende consultas con paciencia y es buena explicando. Deja tareas que son examenes de semestres pasados'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '5146c68d4132a8477314fcf3fa2d4c14d0a505ac13ff2169fe1000ae3139fea6'::TEXT, ARRAY[922]::BIGINT[]),
    (224::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-10T00:00:00+00:00'::TIMESTAMPTZ, '5e513e54b893abb508afe89f1dc1107732e0f45a1d7884b303f46393fe5815bc'::TEXT, ARRAY[922]::BIGINT[]),
    (224::BIGINT, 'Es una profe, que se nota que sabe mucho, no solo del curso, sino tambien de cualquier tema de fisica, las clases pueden extenderse un poco pero son muy participativas, no faltar con ninguna tarea, quiz o lectura, todo cuenta al final. Lo malo es que es muy teorica y hace poca practica en clase'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases largas', 'Brinda apoyo']::TEXT[], '2016-11-21T00:00:00+00:00'::TIMESTAMPTZ, '9c7d2460ba519817663dc902721e335620635317c78c8137396136702d11c1ee'::TEXT, ARRAY[604]::BIGINT[]),
    (224::BIGINT, 'Es una persona muy carga, tiene muchos proyectos dentro y fuera del Tec. Se le nota que le gusta enseñar, accesible para preguntarle cualquier duda, el método de enseñanza no fue de mi agrado, sin embargo muy recomendada'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-08-05T00:00:00+00:00'::TIMESTAMPTZ, '896aeda4090574f4fb3b7bc8bb417b3c184c552e84b37b750d7bc2356a9458a4'::TEXT, ARRAY[604]::BIGINT[]),
    (224::BIGINT, 'Buena profesora, muy buena gente, no hace quices, hay que hacer las comprensiones y todo lo que deje, eso lo salva al final a uno, si uno le pone al final le ayuda, explica regular (entendible por lo menos), sus presentaciones casi siempre son el marque con x del examen, ojala nunca faltar a clases'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0a44318ff725abe161fe8551d7a024682521fca47e0923b3b35445a47f9ad42e'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '8e57c1247616e6f79ffb9df693850d4b8463c6295ca9b2e193d0ab0920dff0b0'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'Super pura vida, relajada y divertida.. Explica bien.. Da todo el material necesario (presentaciones, prácticas, examenes viejos)'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'be6a57e8c39946ffbafdb42a8fc5b178103ceec0391b005f6f62da9ae3785038'::TEXT, ARRAY[922]::BIGINT[]),
    (224::BIGINT, 'Es un excelente profe y se preocupa porque usted entienda la materia además de que siempre está dispuesta a aclarar las dudas. Explica bien pero a veces no termina los ejercicios y uno se queda medio perdido. Sabe mucho y da ejemplos de la vida cotidiana con los que uno se entiende mejor.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '3df2da0c68e9edbdde27f79c15b832cd818b2f60e885fa2d79ba99818aa761ff'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'Profesora muy pura vida. Explica muy bien y siempre está dispuesta a evacuar dudas. Su problema radica en que es muy teórica, da las bases para la práctica pero nunca termina un ejercicio, por lo que uno se la tiene que jugar en ese aspecto. Califica el intento, por eso no quita muchos puntos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, '23285f3515ea2652b133ca0f5be7ed85b1f55b355c34f7523b584e884a705fbf'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'Buena persona, se le nota q sabe mucho, pero como profesora no me gusta, no se da a entender cuando explica la materia'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-05-31T00:00:00+00:00'::TIMESTAMPTZ, '179687cd627c3e39741da7782ee71849861e3558be085df0690da74526634471'::TEXT, ARRAY[604]::BIGINT[]),
    (224::BIGINT, 'Pesimaaaa'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-24T00:00:00+00:00'::TIMESTAMPTZ, 'dcc93d93d5e7ed622d0ddc87166f08b6b82c5b3d342ec938cd7812ce7f0f7aaf'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'Es una buena profesora, sin embargo se va mas por lo teórico y casi nunca por lo práctico, responde los correos si son dudas puntuales, de personas que hayan estudiado.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'd19405eac6bdd6b5c0a66d856c1a3b93ade411e3157e5bd96273036f6c7509b5'::TEXT, ARRAY[922, 630, 604, 1369]::BIGINT[]),
    (224::BIGINT, 'el trato con los estudiantes es genial, muy abierta a ayudar y responder dudas, se preocupa por el aprendizaje, sin embargo, ese aprendizaje está condicionado a que el estudiante revise los capítulos del libro y haga los ejercicios que asigna semana a semana.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'bd96d258ee93fd8c19d883ddf87ba7c70d48ecdaff455442ee44d9742834e874'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'Seriamente no se le entiende como explica, no hace ejemplos de práctica y se preocupa por dar solo teoría. Es pura vida y podrá ser muy buena física, pero como profesora no gracias. Nunca más!:)'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'f218eab6eac6476e433c2fab1b79a102385e7fa4e11264192873923f0dcbdf96'::TEXT, ARRAY[604]::BIGINT[]),
    (224::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'faa7752a24f59882b9eb45cc7e2cb475d675cbd63aa167e5a1f4843b39d5b2e7'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '88d566d48b428d7fb6a1d6802f99037ce79c261b6cf65e451635f7a25a825992'::TEXT, ARRAY[4152, 4148]::BIGINT[]),
    (224::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, '7bc0cd34159d05098dc78fc6e74f0745067f721ee83bec80695cdaa2fce93dd6'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'A veces hace la clase un poco tediosa porque da mucha teoria y no muchos ejemplos. Pero es bastante buena y no es dificil de pasar'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'c11e3cc5517b1ba06f10d6f43de3b242e5379734c9dfee923ca32754ed720d88'::TEXT, ARRAY[922]::BIGINT[]),
    (224::BIGINT, 'Como persona y profesora es muy buena. En cuanto como califica, si el resultado del ejercicio no es el correcto,ella igual da puntos por el procedimiento y no baja muchos puntos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-22T00:00:00+00:00'::TIMESTAMPTZ, '1157c2bff1a9586fd266bcc3228889bad882fa4441110171daccbf1490630d34'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'Muy buena Profe, clases divertidas, es muy buena persona y esta dispuesta a aclarar dudas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'de5c770c5d431ed852b3cbe52e5ebc796118800bf82aa56e2042cb625e12fdb1'::TEXT, ARRAY[604, 3021]::BIGINT[]),
    (224::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-09T00:00:00+00:00'::TIMESTAMPTZ, '7933198d56248c77476c13b4041c770a7a1335b2648a1e3d38b80f6146e9982a'::TEXT, ARRAY[4152, 4148]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
